import{_ as e,c as i,o as t,a3 as r}from"./chunks/framework.CoV49S2T.js";const u=JSON.parse('{"title":"服務條款","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/terms.md","filePath":"zh-TW/guide/terms.md","lastUpdated":1787284674000}'),o={name:"zh-TW/guide/terms.md"};function l(h,a,d,p,s,n){return t(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="服務條款" tabindex="-1">服務條款 <a class="header-anchor" href="#服務條款" aria-label="Permalink to &quot;服務條款&quot;">​</a></h1><p>本條款規範你對 ClipboxAI 的使用。下載、安裝或使用 ClipboxAI，即表示你同意本條款。若你不同意，請勿使用本應用程式。</p><h2 id="授權與使用" tabindex="-1">授權與使用 <a class="header-anchor" href="#授權與使用" aria-label="Permalink to &quot;授權與使用&quot;">​</a></h2><p>ClipboxAI 依各版本隨附的授權條款提供。根據授權條款，你獲得一份有限、非專屬、不可轉讓的授權，得在你的 Mac 上使用本應用程式。</p><h2 id="本機優先運作" tabindex="-1">本機優先運作 <a class="header-anchor" href="#本機優先運作" aria-label="Permalink to &quot;本機優先運作&quot;">​</a></h2><p>ClipboxAI 會在你的裝置本地運作，進行剪貼簿管理與裝置端功能。任何剪貼簿歷史都不會傳輸到我們的伺服器。</p><h2 id="雲端-ai-供應商" tabindex="-1">雲端 AI 供應商 <a class="header-anchor" href="#雲端-ai-供應商" aria-label="Permalink to &quot;雲端 AI 供應商&quot;">​</a></h2><p>ClipboxAI 可能會連線到你設定的第三方 AI 供應商。你對該等供應商的使用受其各自的條款與隱私權政策所規範。ClipboxAI 不對第三方供應商的內容、可用性或其做法負責。</p><h2 id="購買" tabindex="-1">購買 <a class="header-anchor" href="#購買" aria-label="Permalink to &quot;購買&quot;">​</a></h2><p>完整功能授權（若有提供）可透過 Mac App Store 取得。所有購買皆由 Apple 處理。ClipboxAI 不經手付款資訊。重新安裝時支援購買還原。</p><h2 id="使用者責任" tabindex="-1">使用者責任 <a class="header-anchor" href="#使用者責任" aria-label="Permalink to &quot;使用者責任&quot;">​</a></h2><ul><li>合法使用 ClipboxAI，並遵守適用規範。</li><li>請勿試圖反編譯、逆向工程，或以違反授權的方式修改應用程式。</li><li>你對傳送給第三方 AI 供應商的內容負責，且必須遵守該等供應商的可接受使用政策。</li></ul><h2 id="隱私" tabindex="-1">隱私 <a class="header-anchor" href="#隱私" aria-label="Permalink to &quot;隱私&quot;">​</a></h2><p>請參閱<a href="/zh-TW/guide/privacy.html">隱私權政策</a>，以了解有關資料處理方式與隱私的資訊。</p><h2 id="無保證" tabindex="-1">無保證 <a class="header-anchor" href="#無保證" aria-label="Permalink to &quot;無保證&quot;">​</a></h2><p>ClipboxAI 係依「現狀」提供，不附任何形式之保證。在法令允許的最大範圍內，維護者免除所有明示、默示、法定或其他形式的保證，包括適售性與特定目的之適用性。</p><h2 id="責任限制" tabindex="-1">責任限制 <a class="header-anchor" href="#責任限制" aria-label="Permalink to &quot;責任限制&quot;">​</a></h2><p>在法令允許的最大範圍內，維護者不對因你使用本應用程式所生任何間接、偶發、特殊、衍生性或懲罰性損害負責。</p><h2 id="終止" tabindex="-1">終止 <a class="header-anchor" href="#終止" aria-label="Permalink to &quot;終止&quot;">​</a></h2><p>若你未能遵守本條款，授予你的權利將自動終止。</p><h2 id="變更" tabindex="-1">變更 <a class="header-anchor" href="#變更" aria-label="Permalink to &quot;變更&quot;">​</a></h2><p>我們可能不時更新本條款。變更後繼續使用即構成接受修訂後的條款。</p><h2 id="聯絡方式" tabindex="-1">聯絡方式 <a class="header-anchor" href="#聯絡方式" aria-label="Permalink to &quot;聯絡方式&quot;">​</a></h2><p>若有關於本條款的疑問，請在專案儲存庫開啟一個 issue： <code>https://github.com/clipboxAI/clipboard-site/issues</code></p><p>或透過電子郵件與我們聯繫：clipboxai@w3cub.com</p><p><em>最後更新：2026 年 8 月 5 日</em></p>',26)])])}const b=e(o,[["render",l]]);export{u as __pageData,b as default};
